(function(){
'use strict';
const pages=['BOM documents','TMP packages','Trade directory'];
const regions=['Northland','Auckland','Waikato','Bay of Plenty','Gisborne','Hawke’s Bay','Taranaki','Manawatū-Whanganui','Wellington','Tasman','Nelson','Marlborough','West Coast','Canterbury','Otago','Southland','Chatham Islands'];
const trades=['Builder / main contractor','Concrete & foundations','Steel erection','Roofing & cladding','Windows & doors','Insulation','Interior lining','Plumbing & drainage','Electrical','Painting','Joinery & cabinetry','Flooring'];
const uid=()=>globalThis.crypto?.randomUUID?.()||`bom-${Date.now()}-${Math.random()}`;
const now=()=>new Date().toISOString();
const pending=new Map();
function init(c){for(const k of ['bomDocuments','documents','inventory','tenderPackages','tradeBusinesses','tenderShortlists','confirmedProjects'])c.store[k] ||= []}
const card=(title,body)=>`<section class="card bt-card"><h2>${title}</h2>${body}</section>`;
function frame(title,sub,body){return `<div class="bt-module"><div class="heading"><div><div class="eyebrow">SHED HOUSE / PROJECT READINESS</div><h1>${title}</h1><p>${sub}</p></div><span class="tag amber">Local demo</span></div>${body}</div>`}
function opts(items,value,e){return items.map(x=>`<option ${x===value?'selected':''}>${e(x)}</option>`).join('')}
function field(label,name,value='',attrs=''){const e=String(value).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));return `<label>${label}<input name="${name}" value="${e}" ${attrs}></label>`}
function select(label,name,items,value,e){return `<label>${label}<select name="${name}">${opts(items,value,e)}</select></label>`}
function area(label,name,value,e){return `<label class="bt-wide">${label}<textarea name="${name}">${e(value||'')}</textarea></label>`}
function projectSelect(c){return `<label class="bt-project">Project<select id="bt-project">${c.projects.map(p=>`<option value="${c.escape(p.id)}" ${p.id===c.projectId?'selected':''}>${c.escape(p.name)} · ${c.escape(p.id)}</option>`).join('')}</select></label>`}
function bomOptions(c){return '<option value="">Select compiled BOM</option>'+c.store.bomDocuments.filter(x=>x.projectId===c.projectId&&x.status!=='Superseded').map(x=>`<option value="${c.escape(x.id)}">${c.escape(x.name)} · ${c.escape(x.version)}</option>`).join('')}
function checkboxes(name,values,selected,e){return `<div class="bt-choices">${values.map(v=>`<label><input name="${name}" type="checkbox" value="${e(v)}" ${selected.includes(v)?'checked':''}> ${e(v)}</label>`).join('')}</div>`}
function render(page,c){init(c);const e=c.escape,s=c.store,pr=c.projectId;
if(page==='BOM documents'){const docs=s.bomDocuments.filter(x=>x.projectId===pr);const preview=pending.get(pr);return frame('A compiled kitset. A traceable inventory.','Keep the actual SH BOM document alongside reviewed inventory rows and project records.',projectSelect(c)+`<div class="bt-grid">${card('Compiled BOM documents',`<p class="small">PDF uploads stay in this browser’s local file storage. They are not extracted automatically or included in deployed source files. Reconcile quantities, cut lengths and kitset inclusions with SH’s approved version.</p>${docs.map(d=>`<article class="bt-record"><span class="tag ${d.status==='Approved'?'':'grey'}">${e(d.status)}</span><h3>${e(d.name)}</h3><p>Version ${e(d.version)} · ${e(d.createdAt)} · ${e(d.attachment.name)}</p><p>${e(d.notes||'')}</p><button class="link" data-bt-download="${e(d.id)}">Download actual PDF</button><form data-bt-status="${e(d.id)}" class="bt-inline">${select('Document status','status',['Compiled','Approved','Superseded'],d.status,e)}<button class="secondary">Update SH review status</button></form><p class="small">${s.inventory.filter(i=>i.projectId===pr&&i.sourceBOMId===d.id).length} linked inventory lines</p></article>`).join('')||'<p>No compiled BOM uploaded for this project.</p>'}<form id="bt-upload" class="bt-form">${field('Document title','name','','required')}${field('BOM version','version','','required')}<label class="bt-wide">Actual compiled PDF · maximum 10 MB<input name="pdf" type="file" accept="application/pdf,.pdf" required></label>${area('SH compilation / review notes','notes','',e)}<button class="primary">Save actual PDF</button></form>`)}${card('Structured inventory import',`<p>Use an SH-reviewed CSV export. Preview it before importing. Required headers:</p><code class="bt-code">category,item_code,description,specification,quantity,unit</code><p class="small">Use specification for cut length, measure and usage. Quantity is the count in the stated unit; 34 sheets of 6.28 m are 34 ea with 6.28 m in specification. Repeated manufacturer codes stay separate by source line.</p><form id="bt-preview"><label>Source BOM<select name="bomId" required>${bomOptions(c)}</select></label><label>CSV file<input name="csvFile" type="file" accept=".csv,text/csv"></label><label>Or paste structured CSV<textarea name="csv" rows="7" placeholder="category,item_code,description,specification,quantity,unit"></textarea></label><button class="secondary">Validate & preview</button></form><div id="bt-preview-result">${previewHTML(preview,c)}</div>`)}</div>`)}
if(page==='TMP packages')return frame('Two packages. One complete build journey.','Prepare separate lockup and fitout scopes for regional builders and specialist trades.',projectSelect(c)+`<div class="banner"><div><h2>Create two demo tender projects</h2><p>Illustrative scopes for a kitset shell to lockup and a separate internal fitout. SH must review consent, site conditions, quantities and each boundary before publishing a real tender.</p></div></div>${card('Demo package setup',`<form id="bt-demo" class="bt-form">${select('Kitset model','model',['Gable 90','Gable 120','Gable 160'],c.project?.model||'Gable 120',e)}${select('Project service region','region',regions,regions.includes(c.project?.place)?c.project.place:'Waikato',e)}<button class="primary">Create / open both demo packages</button></form><p class="small">Stable demo records prevent duplicates. Existing demo scopes are retained on repeat clicks; region and model can be adjusted within each project.</p>`)}${s.tenderPackages.filter(p=>p.projectId===pr).map(p=>packageHTML(p,c)).join('')||card('Project package register','<p>No tender package on the selected project. Use the setup action to create the two example projects, then choose either project above.</p>')}`);
if(page==='Trade directory'){const region=s.tradeTargetRegion||c.project?.place||'Waikato';const pack=s.tenderPackages.find(x=>x.projectId===pr);const needed=pack?.tradeCategories||trades;return frame('Find the right regional team.','Record business identity evidence and service capabilities before shortlisting for a tender.',projectSelect(c)+`<div class="bt-grid">${card('Regional tender candidates',`<label>Target service region<select id="bt-target-region">${opts(regions,region,e)}</select></label><p class="small">Matches are from locally entered records with a manually checked NZBN and service regions confirmed by the business. A registered office address does not prove a service area. No live NZBN lookup or outreach runs here.</p>${needed.map(trade=>{const matches=s.tradeBusinesses.filter(b=>b.verificationStatus==='Manually checked'&&/^\d{13}$/.test(b.nzbn||'')&&b.verificationSource&&b.checkedAt&&(b.regions||[]).includes(region)&&(b.trades||[]).includes(trade));return `<article class="bt-record"><h3>${e(trade)}</h3>${matches.map(b=>{const shortlisted=s.tenderShortlists.some(x=>x.projectId===pr&&x.trade===trade&&x.businessId===b.id);return `<div class="bt-candidate"><div><strong>${e(b.name)}</strong><p class="small">NZBN ${e(b.nzbn)} · ${e(b.capabilities||'')} · checked ${e(b.checkedAt)}</p></div><button class="${shortlisted?'secondary':'primary'}" data-bt-shortlist="${e(b.id)}" data-trade="${e(trade)}" ${shortlisted?'disabled':''}>${shortlisted?'Shortlisted':'Shortlist'}</button></div>`}).join('')||'<p class="small">No manually checked local match for this trade and region.</p>'}</article>`}).join('')}<h3>Project shortlist</h3>${s.tenderShortlists.filter(x=>x.projectId===pr).map(x=>`<p>${e(x.trade)} · ${e(s.tradeBusinesses.find(b=>b.id===x.businessId)?.name||'Business unavailable')} · ${e(x.status)} <button class="link" data-bt-remove-shortlist="${e(x.id)}">Remove</button></p>`).join('')||'<p>No shortlisted businesses.</p>'}`)}${card('Business & trade register',`<p><a href="https://app.nzbn.govt.nz/" target="_blank" rel="noopener noreferrer">Open official NZBN Register ↗</a></p><p class="small">13 digits validate format only. Check identity in the official register and record evidence. Licences, insurance and trade competence need separate verification.</p>${s.tradeBusinesses.map(b=>`<article class="bt-record"><strong>${e(b.name)}</strong><p>${e(b.nzbn)} · ${e(b.verificationStatus)}</p><p class="small">${e((b.regions||[]).join(', '))}<br>${e((b.trades||[]).join(', '))}</p><button class="link" data-bt-business="${e(b.id)}">Edit record</button></article>`).join('')}<form id="bt-business" class="bt-form"><input type="hidden" name="id">${field('Business / legal name','name','','required')}${field('NZBN · 13 digits','nzbn','','inputmode="numeric" pattern="[0-9]{13}" maxlength="13" required')}${select('Identity verification','verificationStatus',['Unchecked','Manually checked'],'Unchecked',e)}${field('Checked on','checkedAt','','type="date"')}${field('Verification source / register evidence','verificationSource')}${field('Business-confirmed service area evidence','regionEvidence','','required')}<fieldset class="bt-wide"><legend>Confirmed regions served</legend>${checkboxes('regions',regions,[],e)}</fieldset><fieldset class="bt-wide"><legend>Trade capabilities</legend>${checkboxes('trades',trades,[],e)}</fieldset>${area('Capability notes / scope limits','capabilities','',e)}${field('Contact email (optional)','email','','type="email"')}${field('Contact phone (optional)','phone')}<button class="primary">Save business record</button><button type="reset" class="secondary">Clear form</button></form><h3>Future NZBN integration</h3><p class="small">The official NZBN API supports business data lookup after subscription. Server credentials and business-confirmed service coverage are required before live targeting.</p><a href="https://www.nzbn.govt.nz/using-the-nzbn/nzbn-services/api/" target="_blank" rel="noopener noreferrer">Official NZBN API access ↗</a>`)}</div>`)}
return '';
}
function previewHTML(p,c){if(!p)return '<p class="small">No preview prepared yet.</p>';const e=c.escape;return `<article class="bt-record"><h3>${p.errors.length?'Import needs correction':'Validated structure · SH reconciliation required'}</h3>${p.errors.length?`<ul>${p.errors.slice(0,30).map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:`<p>${p.rows.length} inventory lines · Source version ${e(p.version)} · ${e(p.bomName)}</p><div class="table-wrap"><table><thead><tr><th>Line / item code</th><th>Category / description</th><th>Specification</th><th>Qty / unit</th></tr></thead><tbody>${p.rows.slice(0,100).map(r=>`<tr><td>${r.sourceLine} · ${e(r.itemCode)}</td><td>${e(r.category)}<br>${e(r.name)}</td><td>${e(r.spec)}</td><td>${r.qty} ${e(r.unit)}</td></tr>`).join('')}</tbody></table></div><p class="small">Showing first 100 lines. All validated lines will import separately. Existing inventory is retained. Import each source version only once.</p><label class="bt-check"><input id="bt-reconciled" type="checkbox"> SH has reconciled every row with the compiled BOM, quantities, units, measures and exclusions.</label><button id="bt-import" class="primary">Import reviewed inventory lines</button>`}</article>`}
function csvParse(text){const rows=[],errors=[];let row=[],cell='',quoted=false,closed=false;const value=String(text).replace(/^\uFEFF/,'');for(let i=0;i<value.length;i++){const ch=value[i];if(quoted){if(ch==='"'){if(value[i+1]==='"'){cell+='"';i++}else{quoted=false;closed=true}}else cell+=ch}else if(ch==='"'){if(cell.trim()||closed){errors.push('Invalid quote in CSV cell');break}quoted=true}else if(ch===','){row.push(cell.trim());cell='';closed=false}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&value[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';closed=false}else{if(closed&&!/\s/.test(ch)){errors.push('Unexpected text after closing quote');break}cell+=ch}}if(quoted)errors.push('Unclosed quoted CSV field');if(cell||row.length){row.push(cell.trim());if(row.some(Boolean))rows.push(row)}return {rows,errors}}
function validateCSV(text){const parsed=csvParse(text),errors=parsed.errors.slice();const headers=['category','item_code','description','specification','quantity','unit'];const raw=parsed.rows;if(!raw.length)return {rows:[],errors:['CSV is empty']};if(raw[0].join(',')!==headers.join(','))errors.push('Headers must be exactly category,item_code,description,specification,quantity,unit');if(raw.length>5001)errors.push('Maximum 5,000 inventory lines per import');const rows=[];for(let i=1;i<raw.length;i++){const r=raw[i];if(r.length!==6){errors.push(`Line ${i+1}: expected six fields`);continue}const [category,itemCode,name,spec,quantity,unit]=r;const qty=Number(quantity);if(!category||!itemCode||!name)errors.push(`Line ${i+1}: category, item_code and description are required`);if(!quantity||!Number.isFinite(qty)||qty<=0)errors.push(`Line ${i+1}: quantity must be positive`);if(!['ea','piece','pieces','m','mm','m2','m²','m3','m³','kg','pack','set','roll','sheet','unit','pair'].includes(unit.toLowerCase()))errors.push(`Line ${i+1}: unsupported unit; use ea, pieces, m, m2, m3, kg, pack, set, roll, sheet or pair`);if(/^(del|delz|zzzzzz)$/i.test(itemCode)||/^end of\b/i.test(name))errors.push(`Line ${i+1}: administrative delivery/separator rows are not supply items`);rows.push({category,itemCode,name,spec,qty,unit,sourceLine:i+1})}if(!rows.length)errors.push('CSV has no inventory rows');return {rows,errors}}
function packageHTML(p,c){const e=c.escape;return card(e(p.title),`<span class="tag amber">${e(p.status)} · Demo scope</span><p>${e(p.type)} · ${e(p.region)} · Version ${e(p.version)}</p><form data-bt-package="${e(p.id)}" class="bt-form">${field('Tender title','title',p.title,'required')}${select('Service region','region',regions,p.region,e)}${select('Kitset model','model',['Gable 90','Gable 120','Gable 160'],c.project?.model||'Gable 120',e)}${field('Scope version','version',p.version,'required')}${select('Status','status',['Draft','Open demo'],p.status,e)}${area('Builder / main contractor scope','scope',p.scope,e)}${area('Inclusions','inclusions',p.inclusions,e)}${area('Exclusions / responsibilities retained by customer or SH','exclusions',p.exclusions,e)}${area('Site readiness / access / services','siteRequirements',p.siteRequirements,e)}${area('Consent, drawing and BOM references','consentReferences',p.consentReferences,e)}${area('Inspection requirements / hold points','inspectionRequirements',p.inspectionRequirements,e)}${area('Proposed milestones · one per line','milestones',(p.milestones||[]).join('\n'),e)}<button class="primary">Save demo package</button></form><h3>Independent trade pricing scopes</h3><p class="small">Tender responses should price each applicable trade separately, state exclusions and programme assumptions, and reconcile against the agreed builder scope.</p>${(p.tradePricingScopes||[]).map(t=>`<details><summary>${e(t.trade)}</summary><p>${e(t.scope)}</p><p><strong>Include:</strong> ${e(t.inclusions)}</p><p><strong>Exclude:</strong> ${e(t.exclusions)}</p></details>`).join('')}<button class="secondary" data-bt-target="${e(p.id)}">Review regional trade candidates →</button>`)}
function demoPackage(type,region){const lock=type==='lockup';const tradeCategories=lock?['Builder / main contractor','Concrete & foundations','Steel erection','Roofing & cladding','Windows & doors']:['Builder / main contractor','Insulation','Interior lining','Plumbing & drainage','Electrical','Painting','Joinery & cabinetry','Flooring'];const pricing={
'Builder / main contractor':['Coordinate programme, subcontractors, site safety, quality records and handover for the specified package.','Scope coordination, labour, temporary protection and agreed site management.','SH kitset material supply; customer changes; other package scope.'],
'Concrete & foundations':['Price setout, earthwork interfaces, foundations and slab to approved site-specific engineering.','Formwork, reinforcing, concrete, anchors and required inspection coordination where specified.','Unspecified ground remediation, service connections and design changes.'],
'Steel erection':['Erect and brace supplied structural members to approved engineering and supplier instructions.','Erection labour, agreed crane/access equipment, temporary bracing and connection checks.','Kitset supply, redesign and replacement of freight-damaged members.'],
'Roofing & cladding':['Install specified roofing, wall cladding, flashings and rainwater goods for the weather envelope.','Installation labour, closures and weatherproofing checks within approved specification.','Optional finishes and items absent from the reconciled BOM.'],
'Windows & doors':['Install specified external windows and doors with documented weatherproof interfaces.','Installation, prescribed flashings/seals and operability checks.','Unspecified glazing upgrades, curtains and internal doors.'],
'Insulation':['Install approved thermal/acoustic insulation within fitout scope.','Specified materials if not SH supplied, installation and prelining documentation.','Envelope redesign and unspecified performance upgrades.'],
'Interior lining':['Price internal framing interfaces, lining, stopping and internal door installation to fitout documents.','Specified lining system, installation and stopping to agreed finish standard.','Structural redesign and unlisted decorative finishes.'],
'Plumbing & drainage':['Price consented plumbing, drainage and fixture fitout by suitably authorised practitioners.','Specified fixtures, rough-in, testing and applicable inspection coordination.','Unspecified utility connections, groundwater works and owner-selected upgrades.'],
'Electrical':['Price approved wiring, fittings and fitout with required testing and certification.','Specified rough-in, fitoff, circuit labelling and compliance documentation.','Unspecified power supply upgrades, appliances and additional circuits.'],
'Painting':['Prepare and paint agreed interior surfaces to documented finish schedule.','Preparation, specified coats, protection and final touchups.','Exterior coating and finishes outside agreed schedule.'],
'Joinery & cabinetry':['Supply/install documented cabinetry and joinery with coordinated dimensions.','Approved layouts, hardware, installation and finish checks.','Unapproved appliances, stone changes and bespoke upgrades.'],
'Flooring':['Prepare substrate and install flooring to approved selections.','Specified flooring, preparation allowances and protection.','Unspecified moisture remediation and owner-selected upgrades.']};
return {id:lock?'TMP-DEMO-LOCKUP':'TMP-DEMO-FITOUT',projectId:lock?'SH-TMP-DEMO-LOCKUP':'SH-TMP-DEMO-FITOUT',type:lock?'Kitset to lockup shell':'Internal fitout',title:lock?'Demo · Kitset to lockup shell':'Demo · Internal fitout',scope:lock?'Coordinate site readiness, consented foundations where included, kitset erection and weather-tight external shell through lockup. SH supplies only the agreed kitset BOM; tenderer prices labour and separately identifies additional supply.':'Coordinate fitout of an accepted lockup shell through agreed internal completion. Price each relevant licensed/specialist trade and interfaces against approved plans and finish schedules.',inclusions:lock?'Approved foundation/anchor scope if awarded; structural erection; specified roof and wall envelope; external opening installation; stage records; shell handover.':'Approved insulation and linings; specified plumbing/electrical; painting; joinery; flooring; testing and staged handover records.',exclusions:lock?'SH kitset supply price; internal fitout; landscaping; unspecified services and ground remediation; variations outside approved scope.':'Structural shell and kitset erection; unlisted services; furniture; landscaping; owner upgrades not in approved selections.',tradeCategories,region,status:'Draft',isDemo:true,version:'1',siteRequirements:'Confirm site address, access, unloading area, storage, ground conditions, service interfaces and work hours before pricing. Demo location is a region only.',consentReferences:'Attach project-specific approved consent plans, engineering and reviewed BOM. No consent reference is assumed for this demonstration.',inspectionRequirements:lock?'Confirm foundation, reinforcing/anchors and envelope inspections with the consent authority. Do not cover work before required approval.':'Confirm prelining, plumbing/drainage and final inspections with the consent authority. Complete required testing and records before handover.',milestones:lock?['Scope & documents accepted','Site and foundations ready','Kitset delivered and checked','Structure erected','Envelope and openings completed','Lockup inspection and handover']:['Lockup shell accepted','Services rough-in','Prelining inspections','Linings and finishes','Fitoff and testing','Final inspection and fitout handover'],tradePricingScopes:tradeCategories.map(trade=>({trade,scope:pricing[trade][0],inclusions:pricing[trade][1],exclusions:pricing[trade][2]}))}
}
function seedTestProjects(c,settings={}){init(c);const s=c.store,model=settings.model||'Gable 120',region=settings.region||'Waikato';let created=0;for(const type of ['lockup','fitout']){const p=demoPackage(type,region);let project=c.projects.find(x=>x.id===p.projectId);if(!project){project={id:p.projectId,name:type==='lockup'?'TMP Demo · Lockup shell':'TMP Demo · Internal fitout',client:'Demonstration customer',place:region,model,stage:'Tender scope preparation',progress:0,date:'To be agreed',isDemo:true};c.projects.push(project);created++;c.notify?.({title:'Demo tender project created',message:`${p.title} · ${region}`,projectId:p.projectId,roles:['staff','customer','contractor'],kind:'tender'})}if(!s.confirmedProjects.some(x=>x.id===project.id))s.confirmedProjects.push(project);if(!s.tenderPackages.some(x=>x.id===p.id))s.tenderPackages.push({...p,region:project.place})}return created}
function bind(page,c){init(c);const s=c.store,$=q=>document.querySelector(q),refresh=()=>{c.save();c.navigate(page)},notify=(title,message,projectId=c.projectId)=>c.notify({title,message,projectId,roles:['staff','customer','contractor'],kind:'tender'});const on=(q,ev,fn)=>{const el=$(q);if(el)el.addEventListener(ev,fn)};const form=(q,fn)=>on(q,'submit',async ev=>{ev.preventDefault();try{if(await fn(Object.fromEntries(new FormData(ev.target)),ev.target)!==false)refresh()}catch(error){c.toast(error.message||'Unable to save local record')}});
on('#bt-project','change',ev=>{s.staffProjectId=ev.target.value;refresh()});
form('#bt-upload',async(d,f)=>{if(!c.files)throw Error('Local file storage unavailable');const file=f.elements.pdf.files[0];if(!file||file.size===0||file.size>10*1024*1024)throw Error('Select a non-empty PDF up to 10 MB');if(!/\.pdf$/i.test(file.name))throw Error('Choose a PDF document');const signature=new TextDecoder().decode(await file.slice(0,1024).arrayBuffer());if(!signature.includes('%PDF-'))throw Error('File content is not a valid PDF');if(s.bomDocuments.some(x=>x.projectId===c.projectId&&x.version===d.version.trim()&&x.status!=='Superseded'))throw Error('This active BOM version already exists. Use a new version or supersede the previous record.');const bomId=uid(),fileId=uid();await c.files.put({id:fileId,projectId:c.projectId,ownerId:bomId,kind:'bom',name:file.name,type:'application/pdf',size:file.size,blob:file,createdAt:now()});const attachment={id:fileId,name:file.name,type:'application/pdf',size:file.size};s.bomDocuments.push({id:bomId,projectId:c.projectId,name:d.name.trim(),version:d.version.trim(),status:'Compiled',attachment,notes:d.notes,createdAt:now()});s.documents.push({id:uid(),projectId:c.projectId,name:d.name.trim(),type:'Kitset BOM',version:d.version.trim(),status:'Compiled',content:'Actual BOM PDF saved locally. SH review and inventory reconciliation required.',attachment,ownerId:bomId,kind:'bom',visibility:['staff','customer','contractor'],uploadedAt:now()});notify('Compiled BOM added',`${d.name} · Version ${d.version}. SH reconciliation required.`);c.toast('Actual PDF saved locally and added to project documents')});
document.querySelectorAll('[data-bt-download]').forEach(button=>button.onclick=async()=>{try{const bom=s.bomDocuments.find(x=>x.id===button.dataset.btDownload&&x.projectId===c.projectId);if(!bom||!c.files)throw Error('BOM file unavailable');const record=await c.files.get(bom.attachment.id);if(!record||record.projectId!==c.projectId||record.ownerId!==bom.id||!record.blob)throw Error('Actual PDF unavailable on this device');const url=URL.createObjectURL(record.blob),a=document.createElement('a');a.href=url;a.download=record.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){c.toast(error.message)}});
document.querySelectorAll('[data-bt-status]').forEach(f=>f.addEventListener('submit',ev=>{ev.preventDefault();const bom=s.bomDocuments.find(x=>x.id===f.dataset.btStatus&&x.projectId===c.projectId);if(!bom)return;const status=new FormData(f).get('status');bom.status=status;for(const d of s.documents.filter(x=>x.projectId===c.projectId&&x.ownerId===bom.id))d.status=status;notify('BOM review status updated',`${bom.name}: ${status}`);refresh()}));
form('#bt-preview',async(d,f)=>{const bom=s.bomDocuments.find(x=>x.id===d.bomId&&x.projectId===c.projectId&&x.status!=='Superseded');if(!bom)throw Error('Select an active BOM on this project');let text=d.csv||'';const file=f.elements.csvFile.files[0];if(file){if(file.size>2*1024*1024)throw Error('CSV file limit is 2 MB');text=await file.text()}const result=validateCSV(text);pending.set(c.projectId,{...result,bomId:bom.id,bomName:bom.name,version:bom.version});c.toast(result.errors.length?'CSV needs correction':'CSV preview ready; reconcile before import')});
on('#bt-import','click',()=>{const p=pending.get(c.projectId);if(!p||p.errors.length||!$('#bt-reconciled')?.checked){c.toast('Confirm SH reconciliation before importing');return}const bom=s.bomDocuments.find(x=>x.id===p.bomId&&x.projectId===c.projectId&&x.status!=='Superseded'&&x.version===p.version);if(!bom){c.toast('Source BOM changed. Prepare a fresh preview.');return}if(s.inventory.some(x=>x.projectId===c.projectId&&x.sourceBOMId===bom.id)){c.toast('This BOM version already has imported inventory. Reconcile it before importing a replacement version.');return}for(const row of p.rows)s.inventory.push({...row,id:uid(),projectId:c.projectId,sourceBOMId:bom.id,sourceBOMVersion:bom.version,sourceIdentity:`${bom.id}:${row.sourceLine}`,status:'To specify',supplier:'',orderReference:'',visibility:['staff','customer','contractor'],reconciled:true});bom.reconciledAt=now();pending.delete(c.projectId);notify('Reviewed BOM inventory imported',`${p.rows.length} lines imported individually from version ${bom.version}.`);c.toast('Reviewed inventory rows imported');refresh()});
form('#bt-demo',d=>{seedTestProjects(c,d);s.staffProjectId='SH-TMP-DEMO-LOCKUP';c.toast('Both demo tender projects ready. Select each project to review its scope.')});
document.querySelectorAll('[data-bt-package]').forEach(f=>f.addEventListener('submit',ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(f)),p=s.tenderPackages.find(x=>x.id===f.dataset.btPackage&&x.projectId===c.projectId);if(!p)return;const {model,...fields}=d;Object.assign(p,fields,{milestones:d.milestones.split('\n').map(x=>x.trim()).filter(Boolean),updatedAt:now()});const project=c.projects.find(x=>x.id===p.projectId);if(project){project.place=d.region;project.model=model;const saved=s.confirmedProjects.find(x=>x.id===project.id);if(saved)Object.assign(saved,project)}notify('Demo tender scope updated',`${p.title} · ${p.status} · ${d.region}`);refresh()}));
document.querySelectorAll('[data-bt-target]').forEach(button=>button.onclick=()=>{const p=s.tenderPackages.find(x=>x.id===button.dataset.btTarget&&x.projectId===c.projectId);if(p){s.tradeTargetRegion=p.region;c.save();c.navigate('Trade directory')}});
on('#bt-target-region','change',ev=>{s.tradeTargetRegion=ev.target.value;refresh()});
form('#bt-business',(d,f)=>{const data=new FormData(f),areas=data.getAll('regions'),capabilities=data.getAll('trades');if(!/^\d{13}$/.test(d.nzbn))throw Error('NZBN format requires exactly 13 digits');if(!areas.length||!capabilities.length)throw Error('Select confirmed service regions and at least one trade');if(d.verificationStatus==='Manually checked'&&(!d.verificationSource.trim()||!d.checkedAt))throw Error('Manual identity verification needs source evidence and checked date');if(s.tradeBusinesses.some(b=>b.nzbn===d.nzbn&&b.id!==d.id))throw Error('NZBN already exists in this local directory');const record={...d,id:d.id||uid(),regions:areas,trades:capabilities,updatedAt:now()};const i=s.tradeBusinesses.findIndex(b=>b.id===record.id);if(i<0)s.tradeBusinesses.push(record);else s.tradeBusinesses[i]=record;c.toast('Business record saved locally. No outreach sent.')});
document.querySelectorAll('[data-bt-business]').forEach(button=>button.onclick=()=>{const b=s.tradeBusinesses.find(x=>x.id===button.dataset.btBusiness),f=$('#bt-business');if(!b)return;for(const [key,value]of Object.entries(b)){if(['regions','trades'].includes(key)){f.querySelectorAll(`[name="${key}"]`).forEach(el=>el.checked=value.includes(el.value))}else if(f.elements[key])f.elements[key].value=value}f.scrollIntoView({behavior:'smooth',block:'center'})});
document.querySelectorAll('[data-bt-shortlist]').forEach(button=>button.onclick=()=>{const b=s.tradeBusinesses.find(x=>x.id===button.dataset.btShortlist),region=s.tradeTargetRegion||c.project?.place||'Waikato',trade=button.dataset.trade;if(!b||b.verificationStatus!=='Manually checked'||!b.verificationSource||!b.checkedAt||!/^\d{13}$/.test(b.nzbn)||!b.regions.includes(region)||!b.trades.includes(trade)){c.toast('Candidate no longer matches checked identity, region and trade');return}if(!s.tenderShortlists.some(x=>x.projectId===c.projectId&&x.businessId===b.id&&x.trade===trade))s.tenderShortlists.push({id:uid(),projectId:c.projectId,businessId:b.id,trade,region,status:'Shortlisted locally',createdAt:now()});c.toast('Candidate shortlisted; no message sent');refresh()});
document.querySelectorAll('[data-bt-remove-shortlist]').forEach(button=>button.onclick=()=>{s.tenderShortlists=s.tenderShortlists.filter(x=>!(x.id===button.dataset.btRemoveShortlist&&x.projectId===c.projectId));refresh()});
}
window.SHBOMTender={pages,render,bind,validateCSV,seedTestProjects};
})();
